begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.uid(label text default 'owner') returns uuid language sql as $$select md5('credit-test:'||label)::uuid$$;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(pg_temp.uid(),'credits@example.com',now(),false),(pg_temp.uid('other'),'other@example.com',now(),false),(pg_temp.uid('unverified'),'new@example.com',null,false);
create function pg_temp.call(action text,input jsonb default '{}') returns jsonb language sql as $$select public.credit_dispatch(pg_temp.uid(),action,input)$$;
create function pg_temp.item(op text default 'image',model text default 'gemini',res text default '2K',n int default 1) returns jsonb language sql as $$select jsonb_build_object('operation',op,'provider',model,'model',case when model='gemini' then 'gemini-3-pro-image' when model='seedream' then 'seedream-5.0-flash' else model end,'resolution',res,'count',n)$$;
select is((pg_temp.call('wallet')->>'availableMinor')::int,1000,'welcome grant');
select is((pg_temp.call('wallet')->>'availableMinor')::int,1000,'welcome replay');
select throws_ok($$select public.credit_dispatch(pg_temp.uid('unverified'),'wallet')$$,'P0001','unauthorized','unverified denied');
select ok(not has_function_privilege('authenticated','public.credit_dispatch(uuid,text,jsonb)','execute'),'client cannot mutate wallet');
select ok(not has_table_privilege('authenticated','private.credit_wallets','update'),'wallet protected');
select throws_ok($$select pg_temp.call('quote',jsonb_build_object('items',jsonb_build_array(pg_temp.item())))$$,'P0001','credits_disabled','billing disabled initially');
update private.credit_settings set enabled=true;
select is((private.credit_quote(jsonb_build_array(pg_temp.item('image','seedream','2K')))->>'totalMinor')::int,30,'Seedream price');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('image','seedream','2K')||'{"model":"seedream-5.0-pro"}'::jsonb))->>'totalMinor')::int,30,'Seedream Pro 2K price');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('image','gemini','1K')))->>'totalMinor')::int,60,'Gemini 1K price');
select is((private.credit_quote(jsonb_build_array(pg_temp.item()))->>'totalMinor')::int,80,'Gemini 2K price');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('chat','doubao','')))->>'totalMinor')::int,2,'Doubao chat');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('chat','minimax','')))->>'totalMinor')::int,3,'MiniMax chat');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('optimize','doubao','')))->>'totalMinor')::int,5,'Doubao optimization');
select is((private.credit_quote(jsonb_build_array(pg_temp.item('optimize','minimax','')))->>'totalMinor')::int,10,'MiniMax optimization');
select is((private.credit_quote(jsonb_build_array(pg_temp.item(),pg_temp.item('image','seedream','2K')))->>'totalMinor')::int,110,'mixed models');
create temporary table credit_test_state(k text primary key,v jsonb);
create function pg_temp.keep(k text,v jsonb) returns void language sql as $$insert into credit_test_state values(k,v) on conflict(k) do update set v=excluded.v$$;
create function pg_temp.state(k text) returns jsonb language sql as $$select v from credit_test_state where credit_test_state.k=$1$$;
create function pg_temp.text_input(label text default 'text') returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.uid(label),'operation','chat','model','doubao','billing',jsonb_build_object('version','2026-10-06.1','totalMinor',2),'input',jsonb_build_object('message','hello'))$$;
select pg_temp.keep('text',pg_temp.call('text_start',pg_temp.text_input()));
select is((pg_temp.call('wallet')->>'frozenMinor')::int,2,'text reservation');
select is(pg_temp.call('text_start',pg_temp.text_input())->>'id',pg_temp.state('text')->>'id','stable text request');
select throws_ok($$select pg_temp.call('text_start',jsonb_set(pg_temp.text_input(),'{input,message}','"different"'))$$,'P0001','idempotency_conflict','changed payload rejected');
select ok((pg_temp.call('text_claim',pg_temp.text_input())->>'claimed')::boolean,'one model claim');
select is(pg_temp.call('text_cancel',pg_temp.text_input())->>'status','processing','a concurrent preflight failure cannot refund a claimed request');
select ok(not (pg_temp.call('text_claim',pg_temp.text_input())->>'claimed')::boolean,'duplicate claim denied');
select pg_temp.call('text_result',pg_temp.text_input()||'{"result":{"content":"saved reply"}}');
select throws_ok($$select pg_temp.call('text_refund',pg_temp.text_input())$$,'P0001','credit_result_must_complete','saved model result cannot be refunded by a late failure');
select pg_temp.keep('completed',pg_temp.call('text_complete',pg_temp.text_input()));
select is(pg_temp.call('text_complete',pg_temp.text_input())->>'result',pg_temp.state('completed')->>'result','completion replay returns same message');
select is((pg_temp.call('wallet')->>'spentMinor')::int,2,'text captured once');
select is((select count(*)::int from public.timeline_items where session_id=(pg_temp.state('text')->>'session_id')::uuid),2,'one user and one assistant saved');
select pg_temp.call('text_start',pg_temp.text_input('unknown'));
select pg_temp.call('text_claim',pg_temp.text_input('unknown'));
select pg_temp.call('text_unknown',pg_temp.text_input('unknown'));
select is((pg_temp.call('wallet')->>'frozenMinor')::int,2,'unknown keeps freeze');
select ok(not (pg_temp.call('text_claim',pg_temp.text_input('unknown'))->>'claimed')::boolean,'unknown never replays provider');
select throws_ok($$select public.credit_dispatch(pg_temp.uid('other'),'text_complete',pg_temp.text_input())$$,'P0001','credit_operation_not_found','cross account denied');
select pg_temp.call('text_start',pg_temp.text_input('failed'));
select pg_temp.call('text_refund',pg_temp.text_input('failed'));
select pg_temp.call('text_refund',pg_temp.text_input('failed'));
select is((pg_temp.call('wallet')->>'frozenMinor')::int,2,'failed refund once');
select throws_ok($$select pg_temp.call('text_start',jsonb_set(pg_temp.text_input('badprice'),'{billing,totalMinor}','1'))$$,'P0001','credit_price_changed','tampered price rejected');
select throws_ok($$select pg_temp.call('text_start',jsonb_set(pg_temp.text_input('oldprice'),'{billing,version}','"old"'))$$,'P0001','credit_price_changed','old price rejected');
-- Real task admission and individual outcomes; no model or external queue service.
update private.runtime_flags set enabled=true where flag='generation_enabled';
update private.provider_runtime_config set enabled=true where provider='gemini';
delete from private.provider_health_windows where provider='gemini';
create function pg_temp.image_input(label text default 'images',n int default 2) returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.uid(label),'prompt','Test image','provider','gemini','model','gemini-3-pro-image','config',jsonb_build_object('count',n,'resolution','2K','aspectRatio','1:1','referenceIds','[]'::jsonb,'registryVersion','2026-08-25.1'),'requestHash',md5(label),'correlationId',gen_random_uuid(),'billing',jsonb_build_object('version','2026-10-06.1','totalMinor',80*n))$$;
select pg_temp.keep('images',pg_temp.call('image',pg_temp.image_input()));
select is((pg_temp.call('wallet')->>'frozenMinor')::int,162,'images freeze per item');
select is(pg_temp.call('image',pg_temp.image_input())->>'batchId',pg_temp.state('images')->>'batchId','transport retry reuses batch despite correlation ID');
select is((pg_temp.call('wallet')->>'frozenMinor')::int,162,'image retry no extra charge');
update public.generations set status='succeeded',provider_submission_state='submitted',storage_bucket='generated',storage_path='credits/'||id,asset_status='active',asset_expires_at=now()+interval '1 day' where id=(select id from public.generations where batch_id=(pg_temp.state('images')->>'batchId')::uuid limit 1);
update public.generations set status='failed',error_code='cancelled',provider_submission_state='not_submitted' where batch_id=(pg_temp.state('images')->>'batchId')::uuid and status='pending';
select is((pg_temp.call('wallet')->>'spentMinor')::int,82,'only successful image charged');
select is((pg_temp.call('wallet')->>'frozenMinor')::int,2,'failed image released');
select pg_temp.keep('images2',pg_temp.call('image',pg_temp.image_input('images2',1)));
update public.generations set status='failed',provider_submission_state='unknown',error_code='provider_result_unknown' where batch_id=(pg_temp.state('images2')->>'batchId')::uuid;
select is((pg_temp.call('wallet')->>'frozenMinor')::int,82,'unknown image remains frozen');
delete from public.generation_batches where id=(pg_temp.state('images')->>'batchId')::uuid;
select is((pg_temp.call('wallet')->>'spentMinor')::int,82,'delete content retains settled ledger');
select is((select count(*)::int from private.credit_ledger where user_id=pg_temp.uid() and kind='capture'),2,'capture ledger survives deletion');
update private.credit_wallets set available_minor=100 where user_id=pg_temp.uid();
select throws_ok($$select pg_temp.call('image',pg_temp.image_input('too-expensive',2))$$,'P0001','insufficient_credits','whole admission rolled back on balance shortage');
select is((pg_temp.call('wallet')->>'availableMinor')::int,100,'no partial debit');
select is((select count(*)::int from private.credit_requests where request_id=pg_temp.uid('too-expensive')),0,'no partial task record');
select lives_ok($$select public.credit_admin(jsonb_build_object('action','grant','userId',pg_temp.uid(),'amountMinor',50,'reason','test grant','actor','test','requestId',pg_temp.uid('grant'),'apply',true))$$,'manual grant');
select lives_ok($$select public.credit_admin(jsonb_build_object('action','grant','userId',pg_temp.uid(),'amountMinor',50,'reason','test grant','actor','test','requestId',pg_temp.uid('grant'),'apply',true))$$,'grant idempotency');
select is((pg_temp.call('wallet')->>'availableMinor')::int,150,'manual grant once');

-- Mixed-model commerce admission is atomic across all slots.
create function pg_temp.mixed_plan() returns jsonb language sql as $$select jsonb_build_object('scene','xhs-poster','templateId','xhs-editorial','brief',jsonb_build_object('contentMode','content','name','Testing poster','facts','Body text','sellingPoints','','platform','xiaohongshu','placement','cover','productReferenceIds','[]'::jsonb,'styleReferenceIds','[]'::jsonb),'slots',jsonb_build_array(jsonb_build_object('id',pg_temp.uid('slot1'),'role','Cover','instruction','','exactText','Testing poster','referenceIds','[]'::jsonb,'provider','gemini','model','gemini-3-pro-image','aspectRatio','1:1','resolution','2K'),jsonb_build_object('id',pg_temp.uid('slot2'),'role','Body','instruction','','exactText','Body text','referenceIds','[]'::jsonb,'provider','seedream','model','seedream-5.0-flash','aspectRatio','1:1','resolution','2K')))$$;
create function pg_temp.compiled() returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('slotId',slot->>'id','prompt','Compiled poster','hash',md5(slot::text),'provider',slot->>'provider','model',slot->>'model','templateVersion','1.0.0','compilerVersion','commerce-1','config',jsonb_build_object('count',1,'aspectRatio','1:1','resolution','2K','referenceIds','[]'::jsonb,'registryVersion','2026-08-25.1'))) from jsonb_array_elements(pg_temp.mixed_plan()->'slots') slot$$;
insert into public.sessions(id,user_id,title) values(pg_temp.uid('commerce-session'),pg_temp.uid(),'Poster');
select pg_temp.keep('commerce',public.commerce_dispatch(pg_temp.uid(),'create',null,jsonb_build_object('requestId',pg_temp.uid('create'),'sessionId',pg_temp.uid('commerce-session'),'plan',pg_temp.mixed_plan()),'create-hash',pg_temp.compiled(),gen_random_uuid()));
select is((pg_temp.call('wallet')->>'availableMinor')::int,150,'saving content poster costs nothing');
create function pg_temp.mixed_submit() returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.uid('mixed-submit'),'taskId',pg_temp.state('commerce')->>'id','revision',1,'slotIds',jsonb_build_array(pg_temp.uid('slot1'),pg_temp.uid('slot2')),'source','direct','requestHash','mixed-hash','correlationId',gen_random_uuid(),'billing',jsonb_build_object('version','2026-10-06.1','totalMinor',110))$$;
update private.provider_runtime_config set enabled=true where provider='seedream';
update private.credit_wallets set available_minor=100 where user_id=pg_temp.uid();
select throws_ok($$select pg_temp.call('commerce',pg_temp.mixed_submit())$$,'P0001','insufficient_credits','mixed slots cannot partially enter queue');
select is((pg_temp.call('wallet')->>'availableMinor')::int,100,'mixed failure restores wallet');
select is((select count(*)::int from private.credit_requests where request_id=pg_temp.uid('mixed-submit')),0,'mixed failure has no receipt');
update private.credit_wallets set available_minor=500 where user_id=pg_temp.uid();
select pg_temp.keep('mixed',pg_temp.call('commerce',pg_temp.mixed_submit()));
select is((pg_temp.call('wallet')->>'availableMinor')::int,390,'mixed models charged exact sum');
select is(pg_temp.call('commerce',pg_temp.mixed_submit())->'runs',pg_temp.state('mixed')->'runs','mixed request replay');
select public.commerce_dispatch(pg_temp.uid(),'cancel',(pg_temp.state('commerce')->>'id')::uuid,jsonb_build_object('requestId',pg_temp.uid('cancel'),'revision',1,'runId',pg_temp.state('mixed')#>>'{runs,0,id}'),'cancel-hash','[]',gen_random_uuid());
select is((pg_temp.call('wallet')->>'availableMinor')::int,500,'unsubmitted cancellation releases all frozen items');
-- Fenced Worker order: generation failure precedes the durable rejection journal update.
select pg_temp.keep('rejected',pg_temp.call('image',pg_temp.image_input('rejected',1)));
insert into private.generation_work(generation_id,user_id,session_id,lease_until,deadline,phase) select g.id,b.user_id,b.session_id,now()+interval '1 minute',now()+interval '1 hour','submitted' from public.generations g join public.generation_batches b on b.id=g.batch_id where b.id=(pg_temp.state('rejected')->>'batchId')::uuid;
update public.generations set status='failed',provider_submission_state='submitted',error_code='provider_error' where batch_id=(pg_temp.state('rejected')->>'batchId')::uuid;
update private.generation_work set phase='cancelled',provider_outcome='rejected' where generation_id in(select id from public.generations where batch_id=(pg_temp.state('rejected')->>'batchId')::uuid);
select is((pg_temp.call('wallet')->>'availableMinor')::int,500,'worker journal rejection releases after generation update');
select pg_temp.keep('processing-unknown',pg_temp.call('image',pg_temp.image_input('processing-unknown',1)));
update public.generations set status='processing',provider_submission_state='submitted',error_code='provider_reconciliation_required' where batch_id=(pg_temp.state('processing-unknown')->>'batchId')::uuid;
select is((select o.status from private.credit_operations o join public.generations g on g.id=o.original_generation_id where g.batch_id=(pg_temp.state('processing-unknown')->>'batchId')::uuid),'needs_review','processing result requiring review updates wallet operation');
select public.credit_admin(jsonb_build_object('action','reconcile','operationId',(select o.id from private.credit_operations o join public.generations g on g.id=o.original_generation_id where g.batch_id=(pg_temp.state('processing-unknown')->>'batchId')::uuid),'outcome','refunded','evidence','Verified upstream rejected this request','actor','test','reason','Manual reconciliation','requestId',pg_temp.uid('reconcile'),'apply',true));
select is((pg_temp.call('wallet')->>'availableMinor')::int,500,'manual verified rejection restores held image funds');
-- Operator price version does not mutate prior operations.
select public.credit_admin(jsonb_build_object('action','price','version','test-v2','prices',(select jsonb_agg(p||jsonb_build_object('unitMinor',(p->>'unitMinor')::int+1)) from private.credit_price_versions,jsonb_array_elements(prices) p where version='2026-10-06.1'),'reason','test price update','actor','test','requestId',pg_temp.uid('price'),'apply',true));
select is((private.credit_quote(jsonb_build_array(pg_temp.item('chat','doubao','')))->>'totalMinor')::int,3,'new price used only for new quotes');
select is((select amount_minor::int from private.credit_operations where business_key='text:'||pg_temp.uid('text') and user_id=pg_temp.uid()),2,'old charge immutable after price change');
select throws_ok($$select pg_temp.call('text_start',pg_temp.text_input('stale-after-price'))$$,'P0001','credit_price_changed','old confirmation rejected after price activation');
-- A pause rejects new charges but completes already-frozen results.
update private.credit_settings set enabled=false;
select pg_temp.call('text_result',pg_temp.text_input('unknown')||'{"result":{"content":"Recovered existing output"}}');
select is(pg_temp.call('text_complete',pg_temp.text_input('unknown'))->>'status','succeeded','pause continues frozen text settlement');
select is((pg_temp.call('wallet')->>'spentMinor')::int,84,'recovered prior output uses original price');
select throws_ok($$select pg_temp.call('text_start',pg_temp.text_input('paused-new'))$$,'P0001','credits_disabled','pause blocks new model charges');
-- Prebilling tasks remain free after activation.
select pg_temp.keep('old',private.submit_image_generation(pg_temp.uid(),null,'Old unbilled task','gemini','gemini-3-pro-image',pg_temp.image_input('legacy',1)->'config','direct',null,null,null,pg_temp.uid('legacy')::text,'legacy-hash',gen_random_uuid()));
update private.credit_settings set enabled=true;
update public.generations set status='succeeded',provider_submission_state='submitted',storage_bucket='generated',storage_path='old/'||id,asset_status='active',asset_expires_at=now()+interval '1 day' where batch_id=(pg_temp.state('old')->>'batchId')::uuid;
select is((pg_temp.call('wallet')->>'spentMinor')::int,84,'old generations never backcharged');
select ok((public.get_commerce_capabilities()->>'contentPosters')::boolean,'deployed validator advertises content posters');

update private.credit_wallets set available_minor=10000 where user_id=pg_temp.uid();
insert into private.quota_ledger(user_id,batch_id,entry_type,amount,business_key) values(pg_temp.uid(),(pg_temp.state('old')->>'batchId')::uuid,'reserve',30,'credit-test:daily-cap');
select throws_ok($$select pg_temp.call('image',pg_temp.image_input('daily-cap',1)||'{"billing":{"version":"test-v2","totalMinor":81}}')$$,'P0001','quota_exceeded','image daily limit remains independent of abundant credits');
select is((pg_temp.call('wallet')->>'availableMinor')::int,10000,'daily rejection never debits wallet');
select public.credit_dispatch(pg_temp.uid('other'),'wallet');
select ok((public.credit_admin(jsonb_build_object('action','audit','userId',pg_temp.uid('other'),'actor','test','reason','Ledger audit'))->>'consistent')::boolean,'operator audit agrees with untouched ledger');
select ok(not (public.credit_admin(jsonb_build_object('action','audit','userId',pg_temp.uid(),'actor','test','reason','Injected balance audit'))->>'consistent')::boolean,'operator audit detects deliberately injected test balance mismatch');
-- Exercise the actual operator path, not a direct UPDATE of the settings table.
select pg_temp.keep('operator-wallet',pg_temp.call('wallet'));
select lives_ok($$select public.credit_admin(jsonb_build_object('action','activate','enabled',false,'actor','test','reason','Acceptance pause','requestId',pg_temp.uid('operator-pause'),'apply',true))$$,'operator can pause billing');
select is((select enabled from private.credit_settings where singleton),false,'operator pause changes singleton setting');
select lives_ok($$select public.credit_admin(jsonb_build_object('action','activate','enabled',true,'actor','test','reason','Acceptance activation','requestId',pg_temp.uid('operator-activate'),'apply',true))$$,'operator can activate billing');
select is((select enabled from private.credit_settings where singleton),true,'operator activation changes singleton setting');
select is(public.credit_admin(jsonb_build_object('action','activate','enabled',true,'actor','test','reason','Acceptance activation','requestId',pg_temp.uid('operator-activate'),'apply',true))->>'replayed','true','operator activation replay is idempotent');
select is(pg_temp.call('wallet'),pg_temp.state('operator-wallet'),'operator pause and activation preserve wallet');
select * from finish();
rollback;
